import {
  useLayoutEffect,
  useRef,
  useState,
  type CSSProperties,
  type HTMLAttributes,
  type ReactNode,
} from "react";
import { createPortal } from "react-dom";
import {
  getAnchoredLayerPosition,
  type AnchoredAlign,
  type AnchoredSide,
  type LayerVariant,
} from "./anchored-layer";
import { useBalsaPortalScope } from "./BalsaPortalScope";
import { mergeClasses } from "./classes";
import { roundedClasses, type Rounded } from "./form";
import {
  capturePortalPresentation,
  type PortalPresentationSnapshot,
} from "./portal-core";
import type { Shadow, ThemeInput, ThemePresentation } from "./theme";
import {
  BalsaThemeContext,
  useControllableState,
  useResolvedThemeProps,
} from "./theme-context";

export type TooltipVariant = LayerVariant;

export interface TooltipProps extends Omit<HTMLAttributes<HTMLElement>, "id"> {
  id: string;
  label: string;
  "data-balsa"?: string;
  "data-palette"?: string;
  side?: AnchoredSide;
  align?: AnchoredAlign;
  sideOffset?: number;
  openDelay?: number;
  closeDelay?: number;
  variant?: TooltipVariant;
  rounded?: Rounded;
  shadow?: Shadow;
  contained?: boolean;
  disabled?: boolean;
  theme?: ThemeInput;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  trigger?: ReactNode;
  children?: ReactNode;
}

const variantClasses: Readonly<Record<TooltipVariant, string[]>> = {
  surface: ["border-balsa-border-strong bg-balsa-surface-elevated text-balsa-surface-elevated-foreground"],
  outline: ["border-balsa-border-strong bg-balsa-background text-balsa-foreground"],
  soft: ["border-balsa-border bg-balsa-muted text-balsa-foreground"],
  glass: ["border-balsa-border/70 bg-balsa-surface/80 text-balsa-surface-foreground backdrop-balsa"],
};

export function Tooltip(rawProps: TooltipProps) {
  const { props, theme } = useResolvedThemeProps("tooltip", "overlays", rawProps, {
    variant: "surface",
    rounded: "lg",
    shadow: "auto",
  } as const);
  const {
    id,
    label,
    "data-balsa": _dataBalsa,
    "data-palette": dataPalette,
    side = "top",
    align = "center",
    sideOffset = 8,
    openDelay = 300,
    closeDelay = 180,
    variant,
    rounded,
    shadow,
    contained = false,
    disabled = false,
    theme: _themeInput,
    open,
    defaultOpen = false,
    onOpenChange,
    trigger,
    className,
    style,
    children,
    ...domProps
  } = props;
  void _dataBalsa;
  void _themeInput;

  const [current, setOpen] = useControllableState({
    value: open,
    defaultValue: defaultOpen,
    onChange: onOpenChange,
  });
  const scope = useBalsaPortalScope();
  const rootRef = useRef<HTMLElement | null>(null);
  const triggerRef = useRef<HTMLElement | null>(null);
  const panelRef = useRef<HTMLElement | null>(null);
  const openTimerRef = useRef<ReturnType<typeof setTimeout>>(undefined);
  const closeTimerRef = useRef<ReturnType<typeof setTimeout>>(undefined);
  const [mounted, setMounted] = useState(false);
  const [resolvedSide, setResolvedSide] = useState<AnchoredSide>(side);
  const [position, setPosition] = useState({ left: 0, top: 0, maxWidth: 0, maxHeight: 0 });
  const [portalSnapshot, setPortalSnapshot] = useState<PortalPresentationSnapshot | null>(null);
  const themeRef = useRef(theme);
  themeRef.current = theme;
  const openRef = useRef(current);
  openRef.current = current;

  const showPanel = mounted && current;
  const portalHost = contained ? null : (scope?.host ?? (mounted ? document.body : null));

  function clearTimers(): void {
    clearTimeout(openTimerRef.current);
    clearTimeout(closeTimerRef.current);
    openTimerRef.current = undefined;
    closeTimerRef.current = undefined;
  }

  function scheduleOpen(): void {
    if (disabled) return;
    clearTimeout(closeTimerRef.current);
    closeTimerRef.current = undefined;
    openTimerRef.current = setTimeout(() => {
      setOpen(true);
    }, Math.max(0, openDelay));
  }

  function scheduleClose(): void {
    clearTimeout(openTimerRef.current);
    openTimerRef.current = undefined;
    closeTimerRef.current = setTimeout(() => {
      setOpen(false);
    }, Math.max(0, closeDelay));
  }

  function updatePosition(): void {
    const triggerElement = triggerRef.current;
    const panelElement = panelRef.current;
    if (!triggerElement || !panelElement || !openRef.current) return;
    const next = getAnchoredLayerPosition(triggerElement, panelElement, {
      side,
      align,
      sideOffset,
      alignOffset: 0,
    });
    const rootRect = rootRef.current?.getBoundingClientRect();
    const left = next.left - (contained ? rootRect?.left ?? 0 : 0);
    const top = next.top - (contained ? rootRect?.top ?? 0 : 0);
    setPosition((currentPosition) => (
      currentPosition.left === left
        && currentPosition.top === top
        && currentPosition.maxWidth === next.maxWidth
        && currentPosition.maxHeight === next.maxHeight
        ? currentPosition
        : { left, top, maxWidth: next.maxWidth, maxHeight: next.maxHeight }
    ));
    setResolvedSide((currentSide) => (currentSide === next.side ? currentSide : next.side));
  }

  function capturePresentation(): void {
    const root = rootRef.current;
    if (!root?.isConnected) return;
    const currentTheme = themeRef.current;
    const presentation: ThemePresentation | undefined = currentTheme.inherited || currentTheme.explicitPresentation
      ? currentTheme.presentation
      : undefined;
    try {
      const snapshot = capturePortalPresentation(root, presentation);
      setPortalSnapshot((currentSnapshot) => (
        currentSnapshot
          && currentSnapshot.themeId === snapshot.themeId
          && currentSnapshot.themeBase === snapshot.themeBase
          && currentSnapshot.paletteId === snapshot.paletteId
          && currentSnapshot.adapt === snapshot.adapt
          ? currentSnapshot
          : snapshot
      ));
    } catch {
      setPortalSnapshot((currentSnapshot) => currentSnapshot);
    }
  }

  useLayoutEffect(() => {
    setMounted(true);
  }, []);

  useLayoutEffect(() => {
    if (!showPanel) return;
    capturePresentation();
    updatePosition();
  }, [showPanel, side, align, sideOffset, contained]);

  useLayoutEffect(() => {
    if (!mounted) return;
    window.addEventListener("resize", updatePosition, { passive: true });
    window.addEventListener("scroll", updatePosition, true);
    return () => {
      clearTimers();
      window.removeEventListener("resize", updatePosition);
      window.removeEventListener("scroll", updatePosition, true);
    };
  }, [mounted, contained, side, align, sideOffset]);

  const panelClasses = mergeClasses(
    "pointer-events-none z-[60] max-w-[calc(100vw-1rem)] overflow-auto border px-balsa-md py-balsa-xs text-sm shadow-balsa-panel outline-none",
    contained ? "absolute" : "fixed",
    roundedClasses[rounded],
    variantClasses[variant],
    className,
  );
  const panelPresentation = portalSnapshot ?? {
    themeId: theme.presentation.id,
    themeBase: theme.presentation.base,
    paletteId: dataPalette,
    style: Object.fromEntries(
      Object.entries(theme.presentation.style).filter(([property]) => property.startsWith("--balsa-")),
    ) as PortalPresentationSnapshot["style"],
  };
  const panelStyle = {
    left: `${position.left}px`,
    top: `${position.top}px`,
    maxWidth: `${position.maxWidth}px`,
    maxHeight: `${position.maxHeight}px`,
    ...panelPresentation.style,
    ...style,
  } as CSSProperties;

  const panel = showPanel ? (
    <span
      id={id}
      ref={panelRef}
      data-balsa="tooltip-panel"
      data-theme={panelPresentation.themeId}
      data-theme-base={panelPresentation.themeBase}
      data-palette={panelPresentation.paletteId}
      data-side={resolvedSide}
      data-variant={variant}
      data-shadow={shadow}
      role="tooltip"
      aria-label={label}
      className={panelClasses}
      style={panelStyle}
    >
      {children}
    </span>
  ) : null;

  return (
    <BalsaThemeContext.Provider value={theme}>
      <span
        {...domProps}
        ref={rootRef}
        data-balsa="tooltip"
        data-theme={theme.explicitPresentation?.id}
        data-theme-base={theme.explicitPresentation?.base}
        data-palette={dataPalette}
        data-state={current ? "open" : "closed"}
        className="relative inline-flex"
        style={theme.explicitPresentation?.style as CSSProperties | undefined}
        onKeyDown={(event) => {
          if (event.key !== "Escape" || !openRef.current) return;
          clearTimers();
          setOpen(false);
        }}
      >
        <span
          id={`${id}-trigger`}
          ref={triggerRef}
          tabIndex={0}
          aria-describedby={current ? id : undefined}
          className="inline-flex cursor-help rounded-sm outline-none focus-visible:ring-2 focus-visible:ring-balsa-focus-ring"
          onMouseEnter={scheduleOpen}
          onMouseLeave={scheduleClose}
          onFocus={scheduleOpen}
          onBlur={scheduleClose}
        >
          {trigger ?? "Tooltip"}
        </span>
        {contained ? panel : (portalHost && panel ? createPortal(panel, portalHost) : null)}
      </span>
    </BalsaThemeContext.Provider>
  );
}

export type AnchoredSide = "top" | "right" | "bottom" | "left";
export type AnchoredAlign = "start" | "center" | "end";
export type LayerVariant = "surface" | "outline" | "soft" | "glass";

export interface AnchoredLayerPosition {
  left: number;
  top: number;
  side: AnchoredSide;
  maxWidth: number;
  maxHeight: number;
}

interface PositionOptions {
  side: AnchoredSide;
  align: AnchoredAlign;
  sideOffset: number;
  alignOffset: number;
  viewportPadding?: number;
}

function opposite(side: AnchoredSide): AnchoredSide {
  if (side === "top") return "bottom";
  if (side === "bottom") return "top";
  if (side === "left") return "right";
  return "left";
}

function availableSpace(
  anchor: DOMRect,
  side: AnchoredSide,
  padding: number,
): number {
  if (side === "top") return anchor.top - padding;
  if (side === "bottom") return window.innerHeight - anchor.bottom - padding;
  if (side === "left") return anchor.left - padding;
  return window.innerWidth - anchor.right - padding;
}

export function getAnchoredLayerPosition(
  anchor: HTMLElement,
  layer: HTMLElement,
  options: PositionOptions,
): AnchoredLayerPosition {
  const padding = options.viewportPadding ?? 8;
  const anchorRect = anchor.getBoundingClientRect();
  const layerRect = layer.getBoundingClientRect();
  const width = Math.min(
    layerRect.width || 320,
    Math.max(0, window.innerWidth - padding * 2),
  );
  const height = Math.min(
    layerRect.height || 240,
    Math.max(0, window.innerHeight - padding * 2),
  );
  const alternate = opposite(options.side);
  const required = (
    options.side === "top" || options.side === "bottom" ? height : width
  ) + options.sideOffset;
  const side = availableSpace(anchorRect, options.side, padding) >= required
    || availableSpace(anchorRect, options.side, padding)
      >= availableSpace(anchorRect, alternate, padding)
    ? options.side
    : alternate;

  let left = anchorRect.left;
  let top = anchorRect.bottom + options.sideOffset;

  if (side === "top") top = anchorRect.top - height - options.sideOffset;
  if (side === "left") left = anchorRect.left - width - options.sideOffset;
  if (side === "right") left = anchorRect.right + options.sideOffset;

  if (side === "top" || side === "bottom") {
    left = options.align === "start"
      ? anchorRect.left
      : options.align === "end"
        ? anchorRect.right - width
        : anchorRect.left + (anchorRect.width - width) / 2;
    left += options.alignOffset;
  } else {
    top = options.align === "start"
      ? anchorRect.top
      : options.align === "end"
        ? anchorRect.bottom - height
        : anchorRect.top + (anchorRect.height - height) / 2;
    top += options.alignOffset;
  }

  return {
    side,
    left: Math.min(
      Math.max(left, padding),
      Math.max(padding, window.innerWidth - width - padding),
    ),
    top: Math.min(
      Math.max(top, padding),
      Math.max(padding, window.innerHeight - height - padding),
    ),
    maxWidth: window.innerWidth - padding * 2,
    maxHeight: window.innerHeight - padding * 2,
  };
}

import { extendTailwindMerge, type ClassNameValue } from "tailwind-merge";

/**
 * Every custom scale has to be declared here, not only defined in CSS.
 *
 * tailwind-merge decides which of two classes wins by knowing they belong to
 * the same group. A scale it has not been told about is not a group, so a
 * component's own `gap-balsa-md` and a caller's `gap-3` both survive the merge
 * and whichever CSS rule happens to come last decides — the caller's override
 * silently stops working. That is what happened the moment the spacing scale
 * landed, and it is invisible in the source: the class list looks right.
 */
const twMerge = extendTailwindMerge({
  extend: {
    theme: {
      radius: ["balsa-control", "balsa-surface", "balsa-panel"],
      text: [
        "balsa-2xs",
        "balsa-xs",
        "balsa-sm",
        "balsa-base",
        "balsa-prose",
        "balsa-lg",
        "balsa-xl",
        "balsa-2xl",
        "balsa-3xl",
        "balsa-4xl",
        "balsa-5xl",
        "balsa-6xl",
      ],
      leading: ["balsa-tight", "balsa-snug", "balsa-normal", "balsa-relaxed", "balsa-prose"],
      tracking: ["balsa-title", "balsa-normal", "balsa-label"],
      shadow: [
        "balsa-control",
        "balsa-surface",
        "balsa-panel",
        "balsa-sm",
        "balsa-md",
        "balsa-lg",
        "balsa-detail",
      ],
      spacing: [
        "balsa-4xs",
        "balsa-3xs",
        "balsa-2xs",
        "balsa-xs",
        "balsa-sm",
        "balsa-md",
        "balsa-lg",
        "balsa-xl",
        "balsa-2xl",
        "balsa-3xl",
        "balsa-section-sm",
        "balsa-section-md",
        "balsa-section-lg",
        "balsa-control-inline",
        "balsa-density-compact",
        "balsa-density-default",
        "balsa-density-comfortable",
      ],
    },
    classGroups: {
      // `backdrop-balsa` is a custom utility rather than a value on a scale, so
      // it has to join the group it competes with by name. Without this a
      // caller's `backdrop-blur-none` and the component's `backdrop-balsa` both
      // survive the merge and CSS order decides which blur wins — the same
      // failure the spacing scale hit the moment it landed.
      "backdrop-blur": ["backdrop-balsa", "backdrop-balsa-overlay"],
    },
  },
});

export function mergeClasses(...inputs: unknown[]): string {
  return twMerge(...(inputs as ClassNameValue[]));
}

export function withoutClassAttribute(
  attrs: Readonly<Record<string, unknown>>,
): Record<string, unknown> {
  return Object.fromEntries(
    Object.entries(attrs).filter(([name]) => name !== "class"),
  );
}

import { CircleAlert, CircleCheckBig } from "lucide-react";
import type { IconComponent } from "./Icon";

export const fieldLabelClasses =
  "mb-balsa-2xs block text-sm font-medium leading-snug text-balsa-foreground";

export const fieldHintClasses = "mt-balsa-2xs block text-sm text-balsa-muted-foreground";

export const textControlClasses =
  "w-full rounded-lg border font-balsa-body text-balsa-input-foreground outline-none transition-[border-color,box-shadow,opacity] placeholder:text-balsa-muted-foreground focus:border-balsa-focus-ring focus:ring-2 focus:ring-balsa-focus-ring/30 disabled:border-balsa-border disabled:bg-balsa-disabled disabled:text-balsa-disabled-foreground";

export const textControlPopupClasses =
  "max-h-64 overflow-auto rounded-lg p-balsa-3xs text-balsa-surface-elevated-foreground shadow-balsa-surface transition-[opacity,transform,visibility] duration-balsa-fast ease-balsa";

export const textControlOptionClasses =
  "flex min-h-8 w-full items-center justify-between rounded-md px-balsa-sm py-balsa-2xs text-left text-sm transition-colors";

/*
 * No bare `border`. Tailwind compiles it to a literal 1px, which outranks the
 * `border-width: var(--balsa-border-width)` the stylesheet sets on these
 * controls -- so a checkbox and a radio kept a 1px edge at every border
 * setting while everything around them moved. The colour utilities stay; only
 * the width comes from the token.
 */
export const choiceInputClasses =
  "shrink-0 cursor-pointer appearance-none outline-none transition-[border-color,background-color,box-shadow,opacity] focus-visible:border-balsa-focus-ring focus-visible:ring-2 focus-visible:ring-balsa-focus-ring/30 disabled:cursor-not-allowed disabled:border-balsa-border disabled:bg-balsa-disabled";

export type FieldStatus = "default" | "validated" | "unvalidated";
export type FieldSize = "sm" | "md";
export type FieldVariant = "outline" | "surface" | "soft" | "glass";
export type Rounded = "none" | "sm" | "md" | "lg" | "xl" | "2xl" | "3xl" | "full";
export type TextareaResize = "none" | "vertical" | "both";

export const roundedClasses: Readonly<Record<Rounded, string>> = {
  none: "rounded-none",
  sm: "rounded-sm",
  md: "rounded-md",
  lg: "rounded-lg",
  xl: "rounded-xl",
  "2xl": "rounded-2xl",
  "3xl": "rounded-3xl",
  full: "rounded-full",
};

/**
 * A surface that may be contained by another one.
 *
 * `auto` means "concentric with whatever contains me": the corner follows the
 * containing surface's radius minus the inset between them, so the gap between
 * the two edges stays even instead of thickening at every corner. A surface
 * standing on its own finds nothing published to nest inside and keeps the
 * ordinary surface radius.
 *
 * Kept apart from `Rounded` because that union is shared with text controls,
 * where there is nothing to be concentric with and `auto` would be a value
 * nobody could act on.
 */
export type SurfaceRounded = Rounded | "auto";

export const surfaceRoundedClasses: Readonly<Record<SurfaceRounded, string>> = {
  ...roundedClasses,
  // Deliberately no class. The radius comes from the concentric rule in
  // balsa-theme.css, keyed on data-rounded="auto"; a utility emitted here would
  // outrank it and pin the corner to one value.
  auto: "",
};

const fieldVariantClasses: Readonly<Record<FieldVariant, string>> = {
  outline: "border-balsa-input-border bg-balsa-background",
  surface: "border-balsa-input-border bg-balsa-input",
  soft: "border-transparent bg-balsa-muted",
  glass: "border-balsa-border/70 bg-balsa-surface/70 backdrop-balsa",
};

const fieldPopupVariantClasses: Readonly<Record<FieldVariant, string>> = {
  outline: "border-balsa-input-border bg-balsa-background",
  surface: "border-balsa-border-strong bg-balsa-surface-elevated",
  soft: "border-transparent bg-balsa-muted",
  glass: "border-balsa-border/70 bg-balsa-surface/80 backdrop-balsa",
};

export interface AnchoredPopupPosition {
  left: number;
  top: number;
  width: number;
}

const textControlSizeClasses: Record<FieldSize, string[]> = {
  sm: ["h-8", "px-balsa-md", "text-sm"],
  md: ["h-9", "px-balsa-md", "text-sm"],
};

const textareaResizeClasses: Readonly<Record<TextareaResize, string>> = {
  none: "resize-none",
  vertical: "resize-y",
  both: "resize",
};

export const fieldStatusMessages: Record<
  Extract<FieldStatus, "unvalidated">,
  string
> = {
  unvalidated: "Check this information and try again.",
};

export function getTextControlClasses(
  status: FieldStatus,
  hasAdornment: boolean,
  disabled: boolean,
  loading: boolean,
  size: FieldSize = "md",
  rounded: Rounded = "lg",
  variant: FieldVariant = "surface",
): string[] {
  const resolvedSize = textControlSizeClasses[size] ? size : "md";
  return [
    textControlClasses,
    fieldVariantClasses[variant],
    roundedClasses[rounded],
    ...textControlSizeClasses[resolvedSize],
    ...(loading
      ? ["disabled:cursor-progress"]
      : disabled
        ? ["disabled:cursor-not-allowed"]
        : ["cursor-pointer"]),
    ...(status === "validated" ? ["border-balsa-success", "focus:border-balsa-success"] : []),
    ...(status === "unvalidated"
      ? ["border-balsa-destructive", "focus:border-balsa-destructive", "focus:ring-balsa-destructive/30"]
      : []),
    ...(hasAdornment ? ["pr-10"] : []),
  ];
}

export function getTextControlPopupClasses(
  rounded: Rounded = "lg",
  variant: FieldVariant = "surface",
): string[] {
  return [textControlPopupClasses, roundedClasses[rounded], fieldPopupVariantClasses[variant]];
}

export function getTextareaControlClasses(
  status: FieldStatus,
  disabled: boolean,
  loading: boolean,
  size: FieldSize = "md",
  rounded: Rounded = "lg",
  resizable: TextareaResize = "vertical",
  hasAdornment = false,
  variant: FieldVariant = "surface",
): string[] {
  return [
    textControlClasses,
    fieldVariantClasses[variant],
    "h-auto min-h-0 py-balsa-xs leading-6",
    roundedClasses[rounded],
    textareaResizeClasses[resizable],
    size === "sm" ? "px-balsa-md text-sm leading-5" : "px-balsa-md text-sm leading-6",
    ...(loading
      ? ["disabled:cursor-progress"]
      : disabled
        ? ["disabled:cursor-not-allowed"]
        : ["cursor-text"]),
    ...(status === "validated" ? ["border-balsa-success", "focus:border-balsa-success"] : []),
    ...(status === "unvalidated"
      ? ["border-balsa-destructive", "focus:border-balsa-destructive", "focus:ring-balsa-destructive/30"]
      : []),
    ...(hasAdornment ? ["pr-10"] : []),
  ];
}

export function getChoiceInputClasses(variant: FieldVariant = "surface"): string[] {
  return [choiceInputClasses, fieldVariantClasses[variant]];
}

export function getChoiceTrackClasses(variant: FieldVariant = "surface"): string {
  return fieldVariantClasses[variant];
}

export function getAnchoredPopupPosition(
  trigger: HTMLElement,
  popup: HTMLElement,
  fallbackHeight = 256,
): AnchoredPopupPosition {
  const triggerRect = trigger.getBoundingClientRect();
  const popupRect = popup.getBoundingClientRect();
  const viewportPadding = 8;
  const gap = 8;
  const width = Math.min(
    triggerRect.width,
    window.innerWidth - viewportPadding * 2,
  );
  const height = popupRect.height || fallbackHeight;
  const maxLeft = Math.max(
    viewportPadding,
    window.innerWidth - width - viewportPadding,
  );

  return {
    width,
    left: Math.min(Math.max(triggerRect.left, viewportPadding), maxLeft),
    top:
      triggerRect.bottom + gap + height <= window.innerHeight - viewportPadding
        ? triggerRect.bottom + gap
        : Math.max(viewportPadding, triggerRect.top - height - gap),
  };
}

export function getFieldStatusIcon(status: FieldStatus): IconComponent | undefined {
  if (status === "validated") return CircleCheckBig;
  if (status === "unvalidated") return CircleAlert;
  return undefined;
}

export function getFieldStateColorClass(status: FieldStatus): string {
  if (status === "unvalidated") return "text-balsa-destructive";
  if (status === "validated") return "text-balsa-success";
  return "text-balsa-muted-foreground";
}
